def btn(label,href,style='dark',extra=''):
 return f'<a class="btn btn-{style} {extra}" href="{esc(href,quote=True)}"><span>{esc(label)}</span><span aria-hidden="true" class="btn-arrow">↗</span></a>'

def header(active):
 nav=''.join(f'<a class="nav-link {"active" if active==url else ""}" href="{url}" {"aria-current=\"page\"" if active==url else ""}>{esc(label)}</a>' for label,url in NAV)
 mobile=''.join(f'<a href="{url}" class="mobile-nav-link">{esc(label)}<span aria-hidden="true">↗</span></a>' for label,url in NAV)
 return f'''<a class="skip-link" href="#main-content">Skip to main content</a>
 <div class="utility-bar"><div class="container utility-inner"><span>Nyasa Road · Nairobi, Kenya</span><div class="utility-links"><a href="mailto:{EMAIL}">{EMAIL}</a><a href="tel:{PHONE_E164}">{PHONE_DISPLAY}</a></div></div></div>
 <header class="site-header" id="site-header"><div class="container nav-wrap"><a href="/" class="brand" aria-label="Joan Kimani and Company Advocates home"><img src="/assets/joan-kimani-logo.png" alt="Joan Kimani and Company Advocates logo" width="340" height="90"></a><nav class="desktop-nav" aria-label="Main navigation">{nav}</nav><div class="header-actions"><a class="header-consult" href="/contact/">Consult Our Office <span aria-hidden="true">↗</span></a><button type="button" class="menu-trigger" aria-label="Open navigation menu" aria-expanded="false" aria-controls="mobile-panel" data-mobile-open><span></span><span></span><span></span></button></div></div></header>
 <div id="mobile-backdrop" class="menu-backdrop" aria-hidden="true"></div><div id="mobile-panel" class="mobile-panel" aria-label="Mobile navigation" aria-hidden="true" inert><div class="mobile-top"><strong>JOAN KIMANI & COMPANY</strong><button type="button" data-mobile-close aria-label="Close navigation menu">×</button></div><nav aria-label="Mobile links">{mobile}</nav>{btn('Request a Consultation','/contact/','gold','mobile-cta')}<div class="mobile-contact"><a href="tel:{PHONE_E164}">{PHONE_DISPLAY}</a><a href="mailto:{EMAIL}">{EMAIL}</a></div></div>'''

