def contact():
 opts=''.join(f'<option value="{esc(p["title"],quote=True)}">{esc(p["title"])}</option>' for p in PRACTICES)
 return page_hero('CONTACT OUR OFFICE','Let’s talk about<br>what comes next.','Reach the firm directly by telephone, WhatsApp or email, or prepare a brief enquiry below.')+f'''<section class="section"><div class="container contact-grid"><div class="contact-info"><span class="eyebrow">GET IN TOUCH</span><h2>We’re here to listen.</h2><p>Start with a short description of the type of assistance you require. Please do not include confidential documents or sensitive personal information in an initial enquiry.</p><div class="contact-point"><span>CALL OUR OFFICE</span><a href="tel:{PHONE_E164}">{PHONE_DISPLAY}</a></div><div class="contact-point"><span>EMAIL</span><a href="mailto:{EMAIL}">{EMAIL}</a></div><div class="contact-point"><span>VISIT US</span><address>{ADDRESS}</address></div>{btn('Start a WhatsApp Enquiry',WA_URL,'dark')}</div><div class="contact-form-card"><span class="eyebrow">SEND AN ENQUIRY</span><h3>Prepare your message.</h3><p>Complete the fields and your email application will open with your message ready to send.</p><form id="enquiry-form"><div class="form-grid"><div class="field"><label for="full-name">Full name <span>*</span></label><input id="full-name" name="name" type="text" placeholder="Your full name" autocomplete="name" required maxlength="120"></div><div class="field"><label for="email">Email address <span>*</span></label><input id="email" name="email" type="email" placeholder="you@example.com" autocomplete="email" required maxlength="200"></div><div class="field full"><label for="phone">Phone number</label><input id="phone" name="phone" type="tel" placeholder="07XX XXX XXX" autocomplete="tel" maxlength="30"></div><div class="field full"><label for="area">Area of enquiry <span>*</span></label><select id="area" name="area" required><option value="">Select an area</option>{opts}<option value="Other legal enquiry">Other legal enquiry</option></select></div><div class="field full"><label for="message">Brief message <span>*</span></label><textarea id="message" name="message" rows="5" minlength="10" maxlength="3000" placeholder="Briefly describe the assistance you need" required></textarea></div><div class="honeypot" aria-hidden="true"><label for="company_website">Website</label><input id="company_website" name="company_website" tabindex="-1" autocomplete="off"></div><label class="check-label full"><input id="privacy-accept" type="checkbox" required><span>I have read the <a href="/privacy/" target="_blank" rel="noopener noreferrer">Privacy Notice</a> and understand this opens my own email application.</span></label></div><button class="btn btn-dark submit-btn" type="submit"><span>Prepare Email Enquiry</span><span aria-hidden="true">↗</span></button><p class="form-assurance" id="form-status" role="status">This form does not send data to a website server. You must click Send in your email application. An enquiry does not create an advocate–client relationship.</p></form></div></div></section>
 <section class="section map-section"><div class="container"><span class="eyebrow">VISIT OUR OFFICE</span><h2>Find us in Nairobi.</h2><p>{ADDRESS}</p><div class="location-panel"><div class="location-visual"><iframe title="OpenStreetMap showing general area of Nairobi, not a verified building pin" loading="lazy" referrerpolicy="no-referrer-when-downgrade" src="https://www.openstreetmap.org/export/embed.html?bbox=36.80%2C-1.32%2C36.88%2C-1.27&amp;layer=mapnik"></iframe></div><div class="location-details"><span class="eyebrow">OUR LOCATION</span><h3>Joan Kimani & Company Advocates</h3><address>{ADDRESS}</address><p>The map shows the general Nairobi area; it is not a verified office-building pin.</p>{btn('Open Directions',DIRECTIONS,'outline')}</div></div></div></section>'''

def privacy():
 return page_hero('PRIVACY NOTICE','Respecting your privacy.','How this informational website handles initial enquiries.')+f'''<section class="section legal-page"><div class="container prose"><h2>Privacy Notice</h2><p>Last updated: 12 October 2026.</p><h3>Information you choose to share</h3><p>Our contact form prepares a message in your own email application. It does not transmit your form data to a website server. If you send the email, your email provider and the firm receive the information you choose to include.</p><h3>Contacting us</h3><p>If you contact the firm by phone, WhatsApp or email, the relevant communications service may process your information under its own terms. Avoid sending confidential information until an engagement has been agreed.</p><h3>Third-party services</h3><p>This website may load fonts from Google Fonts, illustrative images from Pexels, and a general-location map from OpenStreetMap. These providers may receive technical information such as your IP address when their content loads.</p><h3>Professional confidentiality</h3><p>The firm aims to handle communications professionally and confidentially, subject to applicable law and the terms of any formal engagement.</p><h3>Questions</h3><p>For privacy enquiries, email <a href="mailto:{EMAIL}">{EMAIL}</a>.</p></div></section>'''

def terms():
 return page_hero('WEBSITE TERMS','Important information.','Please read this notice before relying on material published on this website.')+f'''<section class="section legal-page"><div class="container prose"><h2>Website Terms</h2><p>Last updated: 12 October 2026.</p><h3>General information only</h3><p>Material on this website is provided for general information and is not a substitute for legal advice relating to a specific situation.</p><h3>No advocate–client relationship</h3><p>Browsing this website or sending an initial enquiry does not, by itself, establish an advocate–client relationship. A formal professional engagement must be agreed with the firm.</p><h3>Accuracy and updates</h3><p>Legal requirements and procedures may change. Although the website aims to provide useful general information, the firm does not guarantee that every item is complete or current for a particular matter.</p><h3>External services</h3><p>Links to third-party platforms, including WhatsApp, Google Maps, Pexels and OpenStreetMap, are provided for convenience and are governed by their own terms.</p><h3>Contact</h3><p>For questions about this website, contact <a href="mailto:{EMAIL}">{EMAIL}</a>.</p></div></section>'''

pages=[('',NAME,'Your trusted legal partner in Kenya. Property, business, family, litigation, criminal defence and succession legal services from Nairobi.',home(),'/'),('about','About Our Firm','Learn about Joan Kimani and Company Advocates in Nairobi and our approach to client service.',about(),'/about/'),('practice-areas','Practice Areas','Property and land, business law, family law, litigation, criminal defence, succession, debt recovery, employment and more.',practices(),'/practice-areas/'),('managing-partner','Our Advocate','Meet the advocate at Joan Kimani and Company Advocates. Contact our Nairobi office for a legal enquiry.',advocate(),'/managing-partner/'),('insights','Legal Insights','Read introductory legal insights about property, contracts, succession and dispute resolution in Kenya.',insights(),'/insights/'),('contact','Contact Our Office','Contact Joan Kimani and Company Advocates in Nairobi. Call 0716 337 451 or email joankimani840@gmail.com.',contact(),'/contact/'),('privacy','Privacy Notice','Our privacy notice and how initial website enquiries are handled.',privacy(),'/privacy/'),('terms','Website Terms','Website legal terms and general information disclaimer.',terms(),'/terms/')]
for path,title,desc,body,nav in pages:
 destination=ROOT / path / 'index.html' if path else ROOT / 'index.html'
 destination.parent.mkdir(parents=True,exist_ok=True)
 destination.write_text(layout(title,desc,body,nav),encoding='utf-8')
(ROOT/'robots.txt').write_text('User-agent: *\nAllow: /\n',encoding='utf-8')
not_found = page_hero('PAGE NOT FOUND','We can help you find your way.','The page you requested could not be found.')+f'<section class="section"><div class="container"><h2>Let’s get you where you need to be.</h2><p>Please return to the homepage or contact the firm directly.</p>{btn("Go to Homepage","/","dark")}</div></section>'
(ROOT/'404.html').write_text(layout('Page Not Found','Page not found. Explore Joan Kimani & Company Advocates.',not_found,'/nonexistent/'),encoding='utf-8')
print('Generated',len(pages),'pages, a 404 page, and',len(PRACTICES),'practice areas.')
